NEW_FILES = {'migrations/migrate_bank_posters.py': '#!/usr/bin/env python3\n"""\nmigrate_bank_posters.py  --  a bank\'s printed offers and its name over the teller line (0.283.0)\n==============================================================================================\nOne-shot, idempotent migration over specs/*.json. Furnish hangs a bank lobby\'s printed offers (Zoo 1.137.0\'s\n`poster_wall` form `bank`, the `bank_lobby` recipe\'s `poster_wall_bank`) and makes a bank\'s teller line Zoo\'s\n`teller_line` form `bank` in its door sign\'s variant (`level_design.dress_bank_teller_lines`). The library is a fixed\npoint of its furnishing pass, so every spec with a bank lobby or a teller line to dress is refurnished\n(`migrate_furnish_recipes.migrate`); no other spec is touched.\n\n`lf_*` specs are Level Factory\'s per-run transients and are skipped.\n\n    python migrations/migrate_bank_posters.py            # write specs/\n    python migrations/migrate_bank_posters.py --check    # report only; exit 1 if any would change\n"""\nimport glob\nimport io\nimport copy\nimport json\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, HERE)\nsys.path.insert(0, os.path.join(HERE, "migrations"))\n\nimport level_design  # noqa: E402\nimport migrate_furnish_recipes  # noqa: E402\n\ndef _touched(d):\n    b = level_design.club_building_id(d)\n    if any(level_design._room_kind(r, b) == "bank_lobby" for r in d.get("rooms") or []):\n        return True\n    # a credit union is no `bank_lobby` (`lights.is_bank` reads "bank") but its sign is a bank\'s, and so its line\n    return level_design.dress_bank_teller_lines(copy.deepcopy(d)) > 0\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    check = "--check" in argv\n    root = os.path.join(HERE, "specs")\n    changed = 0\n    for p in sorted(glob.glob(os.path.join(root, "*.json"))):\n        if os.path.basename(p).startswith("lf_"):\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        if not _touched(d):\n            continue\n        before = json.dumps(d, indent=1) + "\\n"\n        migrate_furnish_recipes.migrate(d)\n        # ...and a spec with no rooms, which furnish never reaches: `bank`\'s line is dressed all the same\n        level_design.dress_bank_teller_lines(d)\n        after = json.dumps(d, indent=1) + "\\n"\n        if after == before:\n            continue\n        changed += 1\n        names = [str(v.get("name", "")) for v in d["volumes"]]\n        lines = [v for v in d["volumes"] if v.get("form") == "bank" and "teller" in str(v.get("name", ""))]\n        print(f"[bank_posters] {os.path.basename(p)}: {sum(n.startswith(\'poster_wall_bank\') for n in names)} "\n              f"poster run(s), {len(lines)} teller line(s) {[v.get(\'variant\', 0) for v in lines]}")\n        if not check:\n            io.open(p, "w", encoding="utf-8", newline="\\n").write(after)\n    verb = "would change" if check else "refurnished"\n    print(f"[bank_posters] {changed} spec(s) {verb}")\n    return 1 if check and changed else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_bank_posters_teller.py': '"""A bank\'s lobby hangs its printed offers, and its teller line names the bank (0.283.0, the factory\'s roadmap 321).\n\nThe walker\'s bank list: "the rate board and posters", the bank\'s name over the line, a number on every window (the\nfactory\'s docs/reference/BANK_INTERIOR_COMPS.md). Zoo 1.137.0 paints both: `poster_wall` form `bank` and\n`teller_line` form `bank`, whose sixteen variants are the four bank names in the sign\'s four colourways.\n\nFAILS ON 0.282.0: no piece is `poster_wall_bank`, and no teller line carries a form.\n"""\nimport copy\nimport importlib\nimport json\nimport os\nimport re\nimport sys\n\nimport pytest\n\nimport level_design\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nBUILD = os.path.join(HERE, "build")\n\n\ndef _spec(name):\n    return json.load(open(os.path.join(HERE, "specs", name + ".json"), encoding="utf-8"))\n\n\ndef _library():\n    for f in sorted(os.listdir(os.path.join(HERE, "specs"))):\n        if f.endswith(".json") and not f.startswith("lf_"):\n            try:\n                yield f[:-5], _spec(f[:-5])\n            except ValueError:\n                continue\n\n\ndef _zoo(module):\n    from test_furnish import ZOO\n    if not os.path.isfile(os.path.join(ZOO, "zoo_keeper", "core", module.split(".")[-1] + ".py")):\n        pytest.skip("zoo %s not found at %s (set DC_ZOO_ROOT; Zoo >= 1.137.0)" % (module, ZOO))\n    if ZOO not in sys.path:\n        sys.path.insert(0, ZOO)\n    return importlib.import_module("zoo_keeper.core." + module)\n\n\ndef test_the_bank_poster_run_is_a_bank_lobby_fixture_of_zoos_bank_family():\n    p = level_design._PIECES["poster_wall_bank"]\n    assert p["form"] == "bank" and p["where"] == "wall" and p["collision"] == "none"\n    assert "poster_wall_bank" in level_design._RECIPES["bank_lobby"]["fixtures"]\n    assert not any("poster_wall_bank" in (r.get("fixtures") or ())\n                   for k, r in level_design._RECIPES.items() if k != "bank_lobby")\n\n\ndef test_the_run_is_the_height_zoo_hangs_a_bank_sheet_in():\n    PWF = _zoo("poster_wall_forms")\n    if "bank" not in PWF.LAYOUT:\n        pytest.skip("Zoo before 1.137.0 has no bank family")\n    band = PWF.band_height("bank")\n    sheet, gap = PWF.PA.SIZES_M["bank"][0], PWF.LAYOUT["bank"][0]\n    for w, d, h in level_design._PIECES["poster_wall_bank"]["sizes"]:\n        assert abs(h - band) < 1e-9, (w, h, band)\n        # each width holds a whole run, its last sheet not wasted\n        n = int((w + gap) // (sheet + gap))\n        assert n >= 2 and w - (n * sheet + (n - 1) * gap) < 0.05, (w, n)\n\n\ndef test_every_library_bank_lobby_hangs_its_offers():\n    seen = 0\n    for name, d in _library():\n        b = level_design.club_building_id(d)\n        lobbies = [r for r in d.get("rooms") or [] if level_design._room_kind(r, b) == "bank_lobby"]\n        if not lobbies:\n            continue\n        runs = [v for v in d["volumes"] if str(v.get("name", "")).startswith("poster_wall_bank")]\n        assert runs, name\n        assert all(v.get("form") == "bank" for v in runs), name\n        seen += 1\n    assert seen >= 6, seen\n\n\ndef _lines(d):\n    return [v for v, _s, _a in level_design._teller_lines(d)]\n\n\ndef test_every_library_teller_line_names_its_bank():\n    """Every line in a building whose sign is a bank\'s is form `bank`, in the\n    variant `bank_teller_variant` gives its business; nothing else is."""\n    dressed = 0\n    for name, d in _library():\n        b = level_design.club_building_id(d)\n        lines = _lines(d)\n        bankish = bool(set(re.split(r"[^a-z]+", b.lower())) & set(level_design._BANK_SIGN_WORDS))\n        for v in d.get("volumes") or []:\n            if v in lines and bankish:\n                assert v.get("form") == "bank", (name, v["name"])\n                assert int(v.get("variant", 0)) == level_design.bank_teller_variant(b), (name, v["name"])\n                dressed += 1\n            elif "teller" in str(v.get("name", "")):\n                assert v.get("form") != "bank", (name, v["name"])\n    # bank, bank_branch_a02-a04, bank_job, credit_union_a01\n    assert dressed >= 6, dressed\n\n\ndef test_the_tower_desks_are_not_lines():\n    d = _spec("bank_tower_a01")\n    assert not _lines(d)\n    assert not any(v.get("form") == "bank" for v in d["volumes"] if "teller" in v["name"])\n\n\ndef test_dressing_twice_changes_nothing():\n    d = copy.deepcopy(_spec("bank_branch_a02"))\n    assert level_design.dress_bank_teller_lines(d) == 0\n    for v in _lines(d):\n        v.pop("form", None)\n        v.pop("variant", None)\n    assert level_design.dress_bank_teller_lines(d) == len(_lines(d)) == 1\n    assert level_design.dress_bank_teller_lines(d) == 0\n\n\ndef test_the_line_reads_the_name_and_colours_over_the_door():\n    """The cross-check `bank_teller_variant` exists for: Zoo\'s sign over each\n    library bank\'s door and the board its line paints say the same bank in\n    the same colours."""\n    TF = _zoo("teller_line_forms")\n    SN = _zoo("storefront_names")\n    checked = 0\n    for name, d in _library():\n        if not _lines(d):\n            continue\n        b = level_design.club_building_id(d)\n        sign = SN.sign_for(b)\n        if sign["kind"] != "bank":\n            continue\n        v = level_design.bank_teller_variant(b)\n        assert v == TF.variant_for(b), name\n        said = TF.bank_said(v)\n        assert said["text"] == sign["text"] and tuple(said["colours"]) == tuple(sign["colours"]), name\n        checked += 1\n    assert checked >= 6, checked\n\n\ndef test_the_built_slot_asks_zoo_for_the_bank_form():\n    for name in ("bank_branch_a02", "bank_branch_a03", "bank_branch_a04"):\n        path = os.path.join(BUILD, name + ".slots.json")\n        if not os.path.isfile(path):\n            pytest.skip("%s is not built (build.py --all)" % name)\n        slots = json.load(open(path, encoding="utf-8"))\n        slots = slots.get("slots", slots) if isinstance(slots, dict) else slots\n        tellers = [s for s in slots if s.get("species") == "teller_line"]\n        assert tellers, name\n        want = level_design.bank_teller_variant(level_design.club_building_id(_spec(name)))\n        for s in tellers:\n            assert s.get("form") == "bank" and int(s.get("variant") or 0) == want, (name, s.get("slot_id"))\n'}
CHANGELOG = '## [0.283.0] - a bank\'s lobby hangs its printed offers, and its teller line names the bank\n\nThe walker\'s bank list, after the cameras, walls and plants (0.282.0): the rate board and posters, then the bank\'s name\nover the line and a number on every window (the factory\'s docs/reference/BANK_INTERIOR_COMPS.md). Zoo 1.137.0 paints\nboth: `poster_wall` form `bank` and `teller_line` form `bank`.\n\n### Added\n- **`poster_wall_bank`**, a piece: a run of Zoo\'s bank offers, the Christmas Club, free checking and the rate board\n  among them.\n  - Framed and hung square and level at the eye, 0.30 m apart: runs of 2.0, 1.25 and 2.75 m, which are three, two and\n    four 0.46 x 0.62 m sheets.\n  - Its height steps are the library\'s gentlest, 5 cm either side of the eye. Each frame hangs level and a lobby\'s walls\n    differ, not all at one height: the placement guide\'s tell (0.170.0). A first build hung every run at the eye, and\n    `test_poster_walls` refused it on the clone\'s full suite.\n  - Two a lobby, three in a lobby of 150 m2 or more. Off the glass, no collision.\n  - A fixture of `bank_lobby` and nothing else. The seven banks hang two or three runs each.\n- **`dress_bank_teller_lines`**: a bank\'s teller line is Zoo\'s `teller_line` form `bank`, a nameboard over its windows.\n  - Its variant is `bank_teller_variant(business)`, the one whose name and colours Zoo\'s sign over the same building\'s\n    door picks (`storefront_names.sign_for`, keyed on the crc32 of `club_building_id`).\n  - The line names the bank its sign does: bank_branch_a02 variant 11, a03 5, a04 2, bank_job 14, credit_union_a01 8,\n    bank 2.\n  - A LINE is `_teller_lines`\': 6 m and more, 2 m tall. `bank_tower_a01`\'s and `a02`\'s 3 m teller desks are not lines,\n    and each would have numbered its windows 1 and 2.\n  - A building is a bank by the words Zoo\'s sign reads one from (bank, credit, savings), so the credit union\'s line is\n    dressed too; `lights.is_bank` reads "bank" alone.\n  - Run at the end of furnish, from the spec alone; it moves nothing.\n- **`migrations/migrate_bank_posters.py`** refurnishes the eight specs with a bank lobby or a teller line, and dresses\n  `bank`, which has no rooms and so is never furnished.\n  - Nothing else moved but two litter bins. `stand_bins_on_walls` stood them again after the runs took their walls:\n    bank_branch_a02\'s 0.4 m along its wall, bank_tower_a01\'s 5.4 m.\n\n### Tests\n- `tests/test_bank_posters_teller.py` (fails on 0.282.0, seven of eight; the eighth holds that the tower desks are not\n  lines):\n  - the run is a bank lobby\'s fixture of Zoo\'s bank family, at the height Zoo hangs a bank sheet in, and each width\n    holds a whole run;\n  - every library bank lobby hangs its offers;\n  - every library teller line in a bank names it, and nothing else is dressed; dressing twice changes nothing;\n  - with Zoo reachable (`DC_ZOO_ROOT`, Zoo >= 1.137.0): `bank_teller_variant` is Zoo\'s `variant_for`, and the line\n    reads the name and colours over the door of every library bank with a line;\n  - the built slot asks Zoo for the bank form.\n- `tests/test_poster_walls.py`: the bank family joins the library-wide checks (Zoo\'s slot, its band of 0.62 m, the\n  height steps).\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.282.0', 'Deli Counter 0.283.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
